import json
from jsonschema import Draft7Validator

def find_invalid_fields(payload, required):
    data = json.loads(payload)
    schema = {
        'type': 'object',
        'properties': {name: {'type': t} for name, t in required.items()},
        'required': list(required),
    }
    bad = set()
    for err in Draft7Validator(schema).iter_errors(data):
        if err.validator == 'required':
            bad.update(name for name in required if name not in data)
        elif err.path:
            bad.add(err.path[0])
    return sorted(bad)

