import re

LINE_RE = re.compile(r'^(\d{4}-\d{2}-\d{2} \d{2}:\d{2}:\d{2})\s+([A-Z]+)\s+(.*\S)\s*$')

def parse_log_lines(text):
    entries = []
    for line in text.splitlines():
        m = LINE_RE.match(line)
        if m:
            entries.append({'timestamp': m.group(1), 'level': m.group(2), 'message': m.group(3)})
    return entries

