import re

def expand_acronyms(texts, expansions):
    if not expansions:
        return list(texts)
    keys = sorted(expansions, key=len, reverse=True)
    pattern = re.compile(r'\b(?:' + '|'.join(re.escape(k) for k in keys) + r')\b')
    return [pattern.sub(lambda m: expansions[m.group(0)], t) for t in texts]

