import numpy as np

def dominant_frequency(samples, sample_rate):
    x = np.asarray(samples, dtype=float)
    x = x - x.mean()
    spectrum = np.abs(np.fft.rfft(x))
    freqs = np.fft.rfftfreq(len(x), d=1.0 / sample_rate)
    if len(spectrum) > 1:
        spectrum[0] = 0.0
    return float(freqs[int(np.argmax(spectrum))])

