from deepdiff import DeepDiff

def diff_nested_dicts(old, new):
    tree = DeepDiff(old, new, view='tree')
    result = {'added': {}, 'removed': {}, 'changed': {}}
    for item in tree.get('dictionary_item_added', []):
        result['added'][tuple(item.path(output_format='list'))] = item.t2
    for item in tree.get('dictionary_item_removed', []):
        result['removed'][tuple(item.path(output_format='list'))] = item.t1
    for kind in ('values_changed', 'type_changes'):
        for item in tree.get(kind, []):
            result['changed'][tuple(item.path(output_format='list'))] = (item.t1, item.t2)
    return result

