from deepdiff import DeepDiff

def config_changes(old, new):
    diff = DeepDiff(old, new, view='tree')
    def paths(*keys):
        out = []
        for k in keys:
            for level in diff.get(k, []):
                out.append('.'.join(str(p) for p in level.path(output_format='list')))
        return sorted(out)
    return {
        'added': paths('dictionary_item_added'),
        'removed': paths('dictionary_item_removed'),
        'changed': paths('values_changed', 'type_changes'),
    }

