import pytz
from dateutil import parser

def average_gap_seconds(timestamps):
    moments = []
    for text, zone in timestamps:
        naive = parser.parse(text)
        local = pytz.timezone(zone).localize(naive)
        moments.append(local.astimezone(pytz.utc))
    gaps = [(b - a).total_seconds() for a, b in zip(moments, moments[1:])]
    return sum(gaps) / len(gaps)

